use std::fmt::Write as _;
use std::path::Path;

use walkdir::WalkDir;

use crate::error::CodamaError;

const HELPER_IMPORT_PREFIX: &str = "import { ";
const HELPER_MODULE: &str = r#"/**
 * Runtime validation for Pina's zeropod wire types.
 *
 * This file is generated by `pina codama generate`. The stock Codama codecs
 * intentionally permit truncation and permissive decoding, whereas Pina's
 * on-chain zeropod views reject those non-canonical representations.
 */

import {
	type Encoder,
	type FixedSizeDecoder,
	type FixedSizeEncoder,
	addDecoderSizePrefix,
	fixDecoderSize,
	fixEncoderSize,
	getBytesDecoder,
	getU8Decoder,
	transformDecoder,
	transformEncoder,
} from "@solana/kit";

type Integer = bigint | number;

/** Pads valid values but rejects values that would otherwise be truncated. */
export function fixZeroPodEncoderSize<TFrom, TSize extends number>(
	encoder: Encoder<TFrom>,
	fixedBytes: TSize,
): FixedSizeEncoder<TFrom, TSize> {
	const checkedEncoder = transformEncoder(encoder, (value: TFrom) => {
		const encodedSize = "fixedSize" in encoder
			? encoder.fixedSize
			: encoder.getSizeFromValue(value);
		if (encodedSize > fixedBytes) {
			throw new RangeError(
				`zeropod value needs ${encodedSize} bytes but its capacity is ${fixedBytes}`,
			);
		}
		return value;
	});

	return fixEncoderSize(checkedEncoder, fixedBytes);
}

/** Decodes UTF-8 strictly and preserves embedded NUL characters. */
export function getZeroPodStringDecoder<TSize extends number>(
	prefix: FixedSizeDecoder<bigint> | FixedSizeDecoder<number>,
	fixedBytes: TSize,
): FixedSizeDecoder<string, TSize> {
	const bytes = addDecoderSizePrefix(getBytesDecoder(), prefix);
	return transformDecoder(fixDecoderSize(bytes, fixedBytes), (value) =>
		new TextDecoder("utf-8", { fatal: true }).decode(value)
	);
}

/** Accepts only zeropod's canonical boolean encodings. */
export function getZeroPodBooleanDecoder(): FixedSizeDecoder<boolean, 1> {
	return transformDecoder(getU8Decoder(), (value) => {
		if (value !== 0 && value !== 1) {
			throw new RangeError(`invalid zeropod boolean: ${value}`);
		}
		return value === 1;
	});
}

/** Accepts only zeropod's `None` and `Some` option tags. */
export function getZeroPodOptionTagDecoder<
	TDecoded extends Integer,
	TSize extends number,
>(
	decoder: FixedSizeDecoder<TDecoded, TSize>,
): FixedSizeDecoder<TDecoded, TSize> {
	return transformDecoder(decoder, (value) => {
		if (BigInt(value) !== 0n && BigInt(value) !== 1n) {
			throw new RangeError(`invalid zeropod option tag: ${value}`);
		}
		return value;
	});
}

/** Rejects data for a different account or instruction before decoding it. */
export function getZeroPodDiscriminatorDecoder<
	TDecoded extends Integer,
	TSize extends number,
>(
	expected: Integer,
	decoder: FixedSizeDecoder<TDecoded, TSize>,
): FixedSizeDecoder<TDecoded, TSize> {
	return transformDecoder(decoder, (value) => {
		if (BigInt(value) !== BigInt(expected)) {
			throw new RangeError(
				`invalid discriminator: expected ${expected}, received ${value}`,
			);
		}
		return value;
	});
}

/** Rejects numeric enum representations not declared by the native schema. */
export function getZeroPodEnumDecoder<TValue extends number, TSize extends number>(
	decoder: FixedSizeDecoder<TValue, TSize>,
	validValues: readonly TValue[],
): FixedSizeDecoder<TValue, TSize> {
	return transformDecoder(decoder, (value) => {
		if (!validValues.includes(value)) {
			throw new RangeError(`invalid zeropod enum discriminant: ${value}`);
		}
		return value;
	});
}
"#;

pub fn harden_generated_clients(
	output_root: &Path,
	programs: &[String],
) -> Result<(), CodamaError> {
	for program in programs {
		let generated = output_root.join(program).join("src/generated");
		for entry in WalkDir::new(&generated).min_depth(2).max_depth(2) {
			let entry = entry.map_err(|source| {
				CodamaError::HardenJavaScript {
					path: generated.clone(),
					source: std::io::Error::other(source),
				}
			})?;
			let path = entry.path();
			if !is_codec_source(path) {
				continue;
			}

			let source = std::fs::read_to_string(path).map_err(|source| {
				CodamaError::HardenJavaScript {
					path: path.to_path_buf(),
					source,
				}
			})?;
			let hardened = harden_codec_source(&source);
			std::fs::write(path, hardened).map_err(|source| {
				CodamaError::HardenJavaScript {
					path: path.to_path_buf(),
					source,
				}
			})?;
		}

		let helper_path = generated.join("zeropodCodecs.ts");
		std::fs::write(&helper_path, HELPER_MODULE).map_err(|source| {
			CodamaError::HardenJavaScript {
				path: helper_path,
				source,
			}
		})?;
	}

	Ok(())
}

fn is_codec_source(path: &Path) -> bool {
	let Some(parent) = path.parent().and_then(Path::file_name) else {
		return false;
	};

	(parent == "accounts" || parent == "instructions" || parent == "types")
		&& path.extension().is_some_and(|extension| extension == "ts")
}

fn harden_codec_source(source: &str) -> String {
	let mut hardened = source.replace("fixEncoderSize(", "fixZeroPodEncoderSize(");
	hardened = hardened.replace("getBooleanDecoder()", "getZeroPodBooleanDecoder()");
	hardened = harden_optional_account_parsers(&hardened);

	for bits in [8, 16, 32, 64] {
		hardened = replace_string_decoders(&hardened, bits);
	}
	hardened = harden_option_decoders(&hardened);
	hardened = harden_enum_decoder(&hardened);

	if let Some(discriminator) = discriminator_constant(&hardened).map(str::to_owned) {
		for bits in [8, 16, 32, 64] {
			let decoder = format!("getU{bits}Decoder()");
			let replacement = format!("getZeroPodDiscriminatorDecoder({discriminator}, {decoder})");
			hardened = hardened.replace(
				&format!("[\"discriminator\", {decoder}]"),
				&format!("[\"discriminator\", {replacement}]"),
			);
			hardened = hardened.replace(
				&format!("['discriminator', {decoder}]"),
				&format!("['discriminator', {replacement}]"),
			);
		}
	}

	let mut helpers = Vec::new();
	for (name, marker) in [
		("fixZeroPodEncoderSize", "fixZeroPodEncoderSize("),
		("getZeroPodBooleanDecoder", "getZeroPodBooleanDecoder("),
		(
			"getZeroPodDiscriminatorDecoder",
			"getZeroPodDiscriminatorDecoder(",
		),
		("getZeroPodEnumDecoder", "getZeroPodEnumDecoder("),
		("getZeroPodOptionTagDecoder", "getZeroPodOptionTagDecoder("),
		("getZeroPodStringDecoder", "getZeroPodStringDecoder("),
	] {
		if hardened.contains(marker) {
			helpers.push(name);
		}
	}

	if helpers.is_empty() {
		return hardened;
	}
	if hardened.contains("getZeroPodOptionTagDecoder(getU8Decoder())") {
		hardened = ensure_kit_import(&hardened, "getU8Decoder");
	}

	for name in [
		"addDecoderSizePrefix",
		"fixEncoderSize",
		"getBooleanDecoder",
		"getUtf8Decoder",
	] {
		if !hardened.contains(&format!("{name}(")) {
			hardened = remove_import(&hardened, name);
		}
	}

	let import = format!(
		"import {{ {} }} from \"../zeropodCodecs\";\n",
		helpers.join(", ")
	);
	if let Some(offset) = hardened.find(HELPER_IMPORT_PREFIX) {
		hardened.insert_str(offset, &import);
	}

	hardened
}

/// Compare optional fillers against the instruction's effective program
/// address, including builder overrides used for custom deployments.
fn harden_optional_account_parsers(source: &str) -> String {
	const PREFIX: &str = "return accountMeta.address === ";

	let mut remaining = source;
	let mut output = String::with_capacity(source.len());
	while let Some(start) = remaining.find(PREFIX) {
		output.push_str(&remaining[..start + PREFIX.len()]);
		let comparison = &remaining[start + PREFIX.len()..];
		let end = comparison
			.char_indices()
			.find_map(|(index, character)| {
				(!character.is_ascii_alphanumeric() && character != '_' && character != '.')
					.then_some(index)
			})
			.unwrap_or(comparison.len());
		if end == 0 || end == comparison.len() {
			output.push_str(comparison);
			return output;
		}
		output.push_str("instruction.programAddress");
		remaining = &comparison[end..];
	}

	output.push_str(remaining);
	output
}

fn harden_option_decoders(source: &str) -> String {
	let marker = "getOptionDecoder(";
	let mut remaining = source;
	let mut output = String::with_capacity(source.len());

	while let Some(start) = remaining.find(marker) {
		output.push_str(&remaining[..start]);
		let call = &remaining[start..];
		let Some(end) = matching_call_end(call) else {
			output.push_str(call);
			return output;
		};
		let mut hardened_call = call[..=end].to_owned();
		if !hardened_call.contains("getZeroPodOptionTagDecoder(")
			&& hardened_call.contains("noneValue: \"zeroes\"")
		{
			let mut wrapped_custom_prefix = false;
			for bits in [8, 16, 32] {
				let prefix = format!("prefix: getU{bits}Decoder()");
				if hardened_call.contains(&prefix) {
					hardened_call = hardened_call.replace(
						&prefix,
						&format!("prefix: getZeroPodOptionTagDecoder(getU{bits}Decoder())"),
					);
					wrapped_custom_prefix = true;
					break;
				}
			}
			if !wrapped_custom_prefix
				&& let Some(none_value) = hardened_call.find("noneValue: \"zeroes\"")
			{
				hardened_call.insert_str(
					none_value,
					"prefix: getZeroPodOptionTagDecoder(getU8Decoder()), ",
				);
			}
		}

		output.push_str(&hardened_call);
		remaining = &call[end + 1..];
	}

	output.push_str(remaining);
	output
}

fn matching_call_end(call: &str) -> Option<usize> {
	let mut depth = 0usize;
	for (index, character) in call.char_indices() {
		match character {
			'(' => depth = depth.checked_add(1)?,
			')' => {
				depth = depth.checked_sub(1)?;
				if depth == 0 {
					return Some(index);
				}
			}
			_ => {}
		}
	}
	None
}

fn ensure_kit_import(source: &str, name: &str) -> String {
	if source.contains(&format!("{name},")) {
		return source.to_owned();
	}

	let Some(offset) = source.find(HELPER_IMPORT_PREFIX) else {
		return source.to_owned();
	};
	let mut output = source.to_owned();
	output.insert_str(offset + HELPER_IMPORT_PREFIX.len(), &format!("{name}, "));
	output
}

fn harden_enum_decoder(source: &str) -> String {
	let Some((enum_name, variants)) = enum_declaration(source) else {
		return source.to_owned();
	};
	let marker = "return getEnumDecoder(";
	let Some(start) = source.find(marker) else {
		return source.to_owned();
	};
	let expression_start = start + "return ".len();
	let Some(expression_end) = source[expression_start..].find(';') else {
		return source.to_owned();
	};
	let expression_end = expression_start + expression_end;
	let expression = &source[expression_start..expression_end];
	let values = variants
		.iter()
		.map(|variant| format!("{enum_name}.{variant}"))
		.collect::<Vec<_>>()
		.join(", ");

	let mut hardened = String::with_capacity(source.len() + values.len());
	hardened.push_str(&source[..expression_start]);
	let _ = write!(hardened, "getZeroPodEnumDecoder({expression}, [{values}])");
	hardened.push_str(&source[expression_end..]);
	hardened
}

fn enum_declaration(source: &str) -> Option<(&str, Vec<&str>)> {
	let marker = "export enum ";
	let name_start = source.find(marker)? + marker.len();
	let name_end = source[name_start..].find([' ', '{'])? + name_start;
	let name = &source[name_start..name_end];
	let body_start = source[name_end..].find('{')? + name_end + 1;
	let body_end = source[body_start..].find('}')? + body_start;
	let variants = source[body_start..body_end]
		.lines()
		.filter_map(|line| {
			let candidate = line.trim().trim_end_matches(',');
			(!candidate.is_empty()
				&& candidate
					.chars()
					.all(|character| character == '_' || character.is_ascii_alphanumeric()))
			.then_some(candidate)
		})
		.collect::<Vec<_>>();

	(!variants.is_empty()).then_some((name, variants))
}

fn remove_import(source: &str, name: &str) -> String {
	source
		.replace(&format!("\t{name},\n"), "")
		.replace(&format!("  {name},\n"), "")
}

fn replace_string_decoders(source: &str, bits: u8) -> String {
	let needle =
		format!("fixDecoderSize(addDecoderSizePrefix(getUtf8Decoder(), getU{bits}Decoder()), ");
	let mut remaining = source;
	let mut output = String::with_capacity(source.len());

	while let Some(start) = remaining.find(&needle) {
		output.push_str(&remaining[..start]);
		let value_start = start + needle.len();
		let Some(value_end) = remaining[value_start..].find(')') else {
			output.push_str(&remaining[start..]);
			return output;
		};
		let value_end = value_start + value_end;
		let fixed_bytes = &remaining[value_start..value_end];
		if !fixed_bytes
			.chars()
			.all(|character| character.is_ascii_digit())
		{
			output.push_str(&remaining[start..=value_end]);
			remaining = &remaining[value_end + 1..];
			continue;
		}

		let _ = write!(
			output,
			"getZeroPodStringDecoder(getU{bits}Decoder(), {fixed_bytes})"
		);
		remaining = &remaining[value_end + 1..];
	}

	output.push_str(remaining);
	output
}

fn discriminator_constant(source: &str) -> Option<&str> {
	let marker = "export const ";
	let start = source.find(marker)? + marker.len();
	let rest = &source[start..];
	let end = rest.find("_DISCRIMINATOR")? + "_DISCRIMINATOR".len();
	Some(&rest[..end])
}

#[cfg(test)]
mod tests {
	use super::*;

	#[test]
	fn hardens_generated_codec_boundaries() {
		let source = r#"/** generated */
import { fixEncoderSize } from "@solana/kit";
export const PROFILE_STATE_DISCRIMINATOR = 1;
const encoder = fixEncoderSize(addEncoderSizePrefix(getUtf8Encoder(), getU8Encoder()), 33);
const vector = fixEncoderSize(getArrayEncoder(getU64Encoder(), { size: getU16Encoder() }), 66);
const decoder = getStructDecoder([["discriminator", getU8Decoder()], ["name", fixDecoderSize(addDecoderSizePrefix(getUtf8Decoder(), getU8Decoder()), 33)], ["active", getBooleanDecoder()]]);
"#;

		let hardened = harden_codec_source(source);
		assert!(hardened.contains("fixZeroPodEncoderSize("));
		assert!(hardened.contains("getZeroPodStringDecoder(getU8Decoder(), 33)"));
		assert!(hardened.contains("getZeroPodBooleanDecoder()"));
		assert!(hardened.contains(
			"getZeroPodDiscriminatorDecoder(PROFILE_STATE_DISCRIMINATOR, getU8Decoder())"
		));
		assert!(hardened.contains("from \"../zeropodCodecs\""));
	}

	#[test]
	fn leaves_non_codec_sources_unchanged() {
		let source = "export const value = 1;\n";
		assert_eq!(harden_codec_source(source), source);
	}

	#[test]
	fn optional_account_parsers_use_the_effective_program_address() {
		let source = r#"const getNextOptionalAccount = () => {
	const accountMeta = getNextAccount();
	return accountMeta.address === DEFAULT_PROGRAM_ADDRESS
		? undefined
		: accountMeta;
};
"#;
		let expected = source.replace(
			"accountMeta.address === DEFAULT_PROGRAM_ADDRESS",
			"accountMeta.address === instruction.programAddress",
		);
		let hardened = harden_optional_account_parsers(source);
		assert_eq!(hardened, expected);
		assert_eq!(harden_optional_account_parsers(&hardened), expected);
		let single_line =
			"return accountMeta.address === DEFAULT_PROGRAM_ADDRESS ? undefined : accountMeta;\n";
		assert_eq!(
			harden_optional_account_parsers(single_line),
			single_line.replace(
				"accountMeta.address === DEFAULT_PROGRAM_ADDRESS",
				"accountMeta.address === instruction.programAddress",
			)
		);
		let incomplete = "return accountMeta.address === DEFAULT_PROGRAM_ADDRESS";
		assert_eq!(harden_optional_account_parsers(incomplete), incomplete);
	}

	#[test]
	fn hardens_scalar_enum_decoders() {
		let source = r#"/** generated */
import { getEnumDecoder } from "@solana/kit";
export enum Color {
  Red,
  Blue,
}
export function getColorDecoder() {
  return getEnumDecoder(Color);
}
"#;

		let hardened = harden_codec_source(source);
		assert!(
			hardened
				.contains("getZeroPodEnumDecoder(getEnumDecoder(Color), [Color.Red, Color.Blue])")
		);
		assert!(hardened.contains("from \"../zeropodCodecs\""));
	}

	#[test]
	fn hardens_default_and_explicit_option_tags() {
		let source = r#"/** generated */
import { getOptionDecoder, getOptionEncoder, getU16Decoder, getU16Encoder, getU64Decoder, getU64Encoder } from "@solana/kit";
const defaultEncoder = getOptionEncoder(getU64Encoder(), { noneValue: "zeroes" });
const defaultDecoder = getOptionDecoder(getU64Decoder(), { noneValue: "zeroes" });
const wideDecoder = getOptionDecoder(getU64Decoder(), { prefix: getU16Decoder(), noneValue: "zeroes" });
"#;

		let hardened = harden_codec_source(source);
		assert!(hardened.contains(
			"getOptionDecoder(getU64Decoder(), { prefix: \
			 getZeroPodOptionTagDecoder(getU8Decoder()), noneValue: \"zeroes\" })"
		));
		assert!(hardened.contains(
			"prefix: getZeroPodOptionTagDecoder(getU16Decoder()), noneValue: \"zeroes\""
		));
		assert!(
			hardened.contains("import { getZeroPodOptionTagDecoder } from \"../zeropodCodecs\"")
		);
		assert!(hardened.contains("getU8Decoder, "));
		assert!(hardened.contains("getOptionEncoder(getU64Encoder(), { noneValue: \"zeroes\" })"));

		let source_with_u8 = source.replace("getU16Decoder,", "getU16Decoder,\n    getU8Decoder,");
		let hardened = harden_codec_source(&source_with_u8);
		assert_eq!(hardened.matches("getU8Decoder,").count(), 1);
	}

	#[test]
	fn option_hardener_is_idempotent_and_tolerates_incomplete_calls() {
		let hardened = "getOptionDecoder(getU64Decoder(), { prefix: \
		                getZeroPodOptionTagDecoder(getU8Decoder()), noneValue: \"zeroes\" })";
		assert_eq!(harden_option_decoders(hardened), hardened);

		let incomplete = "const decoder = getOptionDecoder(getU64Decoder();";
		assert_eq!(harden_option_decoders(incomplete), incomplete);
		assert_eq!(matching_call_end("getOptionDecoder)"), None);
		assert_eq!(
			ensure_kit_import("export const value = 1;", "getU8Decoder"),
			"export const value = 1;"
		);
	}
}
